def find_insert_position(sorted_values, target):
    """Return the index where target should be inserted to keep the list sorted.

    If target is already present, return the index of its FIRST occurrence.
    """
    low = 0
    high = len(sorted_values)
    while low < high:
        mid = (low + high) // 2
        if sorted_values[mid] < target:
            low = mid + 1
        else:
            high = mid
    return low

def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted((start, end) for start, end in intervals)
    merged = []

    for start, end in sorted_intervals:
        if not merged:
            merged.append([start, end])
        else:
            last_start, last_end = merged[-1]
            if start <= last_end:
                if end > last_end:
                    merged[-1][1] = end
            else:
                merged.append([start, end])

    return merged

package pipeline

import "sync"

// FanIn runs fn over every input concurrently and returns the results in the
// same order as the inputs.
func FanIn(inputs []int, workers int, fn func(int) int) []int {
	out := make([]int, len(inputs))
	if len(inputs) == 0 {
		return out
	}

	if workers <= 0 {
		for i, in := range inputs {
			out[i] = fn(in)
		}
		return out
	}

	jobs := make(chan int)
	var wg sync.WaitGroup

	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = fn(inputs[i])
			}
		}()
	}

	for i := range inputs {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	return out
}

