using System.Collections.Generic;
using UnityEngine;

public class ProjectilePool : MonoBehaviour
{
    [SerializeField] private GameObject prefab;
    [SerializeField] private int prewarmCount;

    private readonly List<GameObject> _pool = new List<GameObject>();
    private readonly HashSet<GameObject> _inPool = new HashSet<GameObject>();

    private void Awake()
    {
        if (prefab == null || prewarmCount <= 0)
        {
            return;
        }

        for (int i = 0; i < prewarmCount; i++)
        {
            GameObject instance = Instantiate(prefab, transform);
            instance.SetActive(false);
            _pool.Add(instance);
            _inPool.Add(instance);
        }
    }

    public GameObject Rent()
    {
        if (_pool.Count > 0)
        {
            GameObject go = _pool[_pool.Count - 1];
            _pool.RemoveAt(_pool.Count - 1);
            _inPool.Remove(go);
            go.SetActive(true);
            return go;
        }

        if (prefab == null)
        {
            return null;
        }

        GameObject go = Instantiate(prefab, transform);
        go.SetActive(true);
        return go;
    }

    public void Return(GameObject go)
    {
        if (go == null)
        {
            return;
        }

        go.SetActive(false);

        if (_inPool.Contains(go))
        {
            return;
        }

        _pool.Add(go);
        _inPool.Add(go);
    }
}

